// interfaces.cpp의 Counter에서 발췌했습니다.
Counter& operator+=(const Counter& rhs) {
    value_ += rhs.value_; // 현재 객체를 변경합니다.
    return *this;        // 변경한 객체의 참조를 돌려줍니다.
}
friend Counter operator+(Counter lhs, const Counter& rhs) {
    lhs += rhs;          // 값으로 받은 왼쪽 사본만 변경합니다.
    return lhs;          // 새 결과를 값으로 반환합니다.
}

// 실제 타입의 일부와 초기화 방식 비교입니다.
explicit Seconds(double value) : value_(value) {
    if (!(value >= 0.0) || value > 3600.0)
        throw std::invalid_argument("seconds");
}

Seconds dt(0.016);      // 직접 초기화: 실제 실습 입력
// Seconds dt = 0.016;  // 복사 초기화: explicit 생성자를 쓰지 못함

// Quantity<T> 안의 friend 정의를 발췌했습니다.
friend Quantity operator+(Quantity a, Quantity b) {
    return Quantity(a.value_ + b.value_);
}

Quantity<int> q(4); // 이때 T는 이미 int입니다.
// 실제 검사는 두 방향의 결과가 모두 7인지 확인합니다.
(q + 3).Value();
(3 + q).Value();

// Notion 원문의 Add 예시에 한국어 설명을 붙였습니다.
template<class T>
T Add(T left, T right) {
    return left + right; // 이 식이 가능하고 결과가 T로 반환되어야 합니다.
}

// Add(1, 2)      : 두 인수에서 T가 int로 일치합니다.
// Add(1, 2.0)    : T가 int와 double로 충돌합니다.
// Add<double>(1, 2.0) : T를 지정한 뒤 인수 변환을 적용합니다.

template<class T>
T Defaulted(T value = T{}); // 함수 인수의 기본값

// Defaulted(3)      : 전달한 3에서 T = int를 추론
// Defaulted<int>()  : T를 지정했으므로 기본 인수를 사용 가능
// Defaulted()       : T를 정할 근거가 없음
// template<class T = int>처럼 템플릿 매개변수 자체의 기본값은 별개입니다.

// templates.cpp: const 객체의 size()를 사용할 수 있어야 합니다.
template<class T>
concept Sized = requires(const T& value) {
    { value.size() } -> std::convertible_to<std::size_t>;
};

template<Sized T>
std::size_t SizeOf(const T& value) {
    return static_cast<std::size_t>(value.size());
}

// 빈 범위는 예외로 거부하고, 첫 값을 복사해서 반환합니다.
template<class Container>
typename Container::value_type FirstCopy(const Container& values) {
    if (values.empty()) throw std::out_of_range("empty");
    return *values.begin();
}

template<class T> struct Base {
    int Read() const { return 42; }
};
template<class T> struct Derived : Base<T> {
    int ReadWithLog() const { return this->Read(); } // 의존 이름 탐색
};

// templates.cpp: offset의 사본을 호출 객체에 저장합니다.
std::function<int(int)> AddLater(int offset) {
    return [offset](int value) { return value + offset; };
}

auto callback = AddLater(5); // AddLater의 매개변수 수명은 끝납니다.
callback(7);                // 저장된 사본5를 더해12를 얻습니다.

// T가 이 함수 호출에서 추론되는 T&&입니다.
template<class T>
std::string ForwardCategory(T&& value) {
    return Category(std::forward<T>(value));
}
// Category(value)라면 value라는 이름의 표현식은 lvalue입니다.
// forward는 타입 추론을 이용해 다음 호출의 범주를 고릅니다.

// templates.cpp의 비소유 포인터 래퍼입니다.
template<class T> struct Borrow {
    T* pointer;
    explicit Borrow(T* p) : pointer(p) {}
    template<class U> requires std::convertible_to<U*, T*>
    Borrow(const Borrow<U>& other) : pointer(other.pointer) {}
};

Cat cat;
Borrow<Cat> child(&cat);
Borrow<const Animal> parent(child); // 업캐스트와 const 추가

// interfaces.cpp의 Label에서 발췌했습니다.
std::string_view View() const & noexcept { return text_; }
std::string_view View() && = delete;
std::string_view View() const && = delete;
std::string Copy() const { return text_; }

Label label("player");
auto view = label.View();                  // label 내부 문자를 관찰
auto copy = Label("temporary").Copy();     // 독립 소유 문자열
// Label("temporary").View();             // 삭제된 오버로드로 거부

// templates.cpp의 실제 구현입니다.
constexpr unsigned PowerOfTwo(unsigned exponent) {
    if (exponent >= 31) throw std::out_of_range("exponent");
    return 1u << exponent;
}
static_assert(PowerOfTwo(10) == 1024); // 상수 평가로 확인
// 전체 main은 PowerOfTwo(31)가 런타임 예외인지 확인합니다.

